//! The Week tab's AI part: the Work summary.
//!
//! It is generated by `main.rs` on its own: when the Week tab is shown (and
//! on the minute tick while it is) if its facts changed since its newest
//! version, 30 seconds after the last change made on the Week tab, and on
//! the summary's schedule. There is no Generate button: the panel only says
//! what is happening ("Updating…"), why it can't ("Can't update: the API
//! key is locked."), or when it last updated. A failed update shows the
//! error and a Retry.
//!
//! The summary is the newest `Summary` version as Markdown. Its heading
//! carries a copy icon (`summary_tools`; the tooltip says "Copied" after a
//! click) and, for a summary edited earlier, Discard edit (an edited
//! summary is not regenerated, so the edit is never lost silently).
//!
//! `load` runs after every message and on every streamed piece, so it
//! returns early on equal data and only reparses Markdown whose source
//! changed; streamed text that grows is pushed incrementally. While a new
//! summary is generated, the previous one stays on screen until the new one
//! is done; only a first summary streams in live.

use fortnight_core::domain::{Report, ReportId, ReportKind, ReportStatus, WeekRef};
use iced::widget::{Column, button, markdown, mouse_area, row, text, tooltip};
use iced::{Center, Element, Font, Padding, Theme, border, color};

use crate::theme;

#[derive(Debug, Clone)]
pub enum Message {
    /// Retry after a failed update.
    Retry(ReportKind),
    DiscardEdit,
    Copy,
    /// The pointer left the copy icon: its tooltip says "Copy" again.
    CopyHoverEnd,
    /// A Markdown link was clicked; ignored on purpose.
    LinkClicked(markdown::Uri),
}

/// What `main.rs` must do.
#[derive(Debug, Clone, PartialEq)]
pub enum Action {
    None,
    /// Generate this kind of report for this week now (Retry).
    Generate(ReportKind, WeekRef),
    /// Save the user's edit of a report version; `None` discards it.
    SaveEdit(ReportId, Option<String>),
    /// Copy this text to the clipboard.
    Copy(String),
}

/// One kind of report for the week.
#[derive(Debug, Clone, PartialEq)]
pub struct ReportSlot {
    pub kind: ReportKind,
    /// Every version, newest first (may include `Failed` ones).
    pub versions: Vec<Report>,
    /// `Some(text so far)` while a version is being generated (streamed).
    pub streaming: Option<String>,
    /// Why it can't be generated right now, e.g. "the API key is locked".
    pub blocked: Option<String>,
    /// There is nothing to summarise or recommend.
    pub empty: bool,
    /// The newest ready version no longer matches the tasks.
    pub stale: bool,
}

/// Everything the panel shows, supplied by `main.rs`.
#[derive(Debug, Clone, PartialEq)]
pub struct ReportPanelData {
    pub week: WeekRef,
    /// The current and past weeks have `[Summary]`, a future week none.
    pub slots: Vec<ReportSlot>,
}

#[derive(Debug, Default)]
pub struct ReportPanel {
    data: Option<ReportPanelData>,
    /// The summary shown (streamed text while generating, otherwise the
    /// newest ready version), parsed, and its source.
    body: markdown::Content,
    body_src: String,
    /// How many times `body` was (re)parsed.
    #[cfg(test)]
    body_parses: u32,
    /// The copy icon was clicked and the pointer hasn't left it since.
    copied: bool,
}

/// A status line under a heading, and whether it is an error.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Status {
    text: String,
    error: bool,
    /// Offer Retry.
    retry: bool,
}

impl ReportPanel {
    pub fn new() -> Self {
        Self::default()
    }

    /// Replaces what the panel shows. Cheap when `data` is unchanged.
    pub fn load(&mut self, data: ReportPanelData) {
        if self.data.as_ref() == Some(&data) {
            return;
        }
        self.data = Some(data);
        self.refresh();
    }

    /// The summary shown: the newest ready version, kept while a new one
    /// is generated (the status line says "Updating…"), so it never blanks
    /// and pops back in. With no earlier version, the new one streams in
    /// live.
    fn refresh(&mut self) {
        let ready = self
            .ready(ReportKind::Summary)
            .and_then(Report::text)
            .map(str::to_owned);
        let body_src = match self.slot(ReportKind::Summary) {
            Some(slot) => match (&slot.streaming, ready) {
                (_, Some(ready)) => ready,
                (Some(so_far), None) => so_far.clone(),
                (None, None) => String::new(),
            },
            None => String::new(),
        };
        if body_src != self.body_src {
            match body_src.strip_prefix(self.body_src.as_str()) {
                Some(more) if !self.body_src.is_empty() => self.body.push_str(more),
                _ => self.body = markdown::Content::parse(&body_src),
            }
            self.body_src = body_src;
            #[cfg(test)]
            {
                self.body_parses += 1;
            }
            self.copied = false;
        }
    }

    pub fn slot(&self, kind: ReportKind) -> Option<&ReportSlot> {
        self.data.as_ref()?.slots.iter().find(|s| s.kind == kind)
    }

    /// The newest ready version of `kind`.
    fn ready(&self, kind: ReportKind) -> Option<&Report> {
        self.slot(kind)?
            .versions
            .iter()
            .find(|r| r.status == ReportStatus::Ready)
    }

    /// What the status line under `kind`'s heading says, if anything.
    fn status(&self, kind: ReportKind) -> Option<Status> {
        let slot = self.slot(kind)?;
        let plain = |s: String| {
            Some(Status {
                text: s,
                error: false,
                retry: false,
            })
        };
        if slot.streaming.is_some() {
            return plain("Updating…".into());
        }
        let ready = self.ready(kind);
        if let Some(reason) = &slot.blocked
            && (ready.is_none() || slot.stale)
        {
            return plain(format!("Can't update: {reason}"));
        }
        if let Some(newest) = slot.versions.first()
            && newest.status == ReportStatus::Failed
            && slot.stale
        {
            let error = newest.error.as_deref().unwrap_or("unknown error");
            return Some(Status {
                text: format!("Couldn't update: {}", first_line(error)),
                error: true,
                retry: slot.blocked.is_none(),
            });
        }
        match ready {
            None if slot.empty => plain("Nothing done this week yet.".into()),
            None => None,
            Some(r) => {
                let mut s = format!("Updated {}", when(r));
                if r.edited_md.is_some() {
                    s.push_str(" · edited");
                }
                plain(s)
            }
        }
    }

    pub fn update(&mut self, message: Message) -> Action {
        match message {
            Message::Retry(kind) => match (&self.data, self.slot(kind)) {
                (Some(data), Some(slot)) if slot.blocked.is_none() && slot.streaming.is_none() => {
                    Action::Generate(kind, data.week)
                }
                _ => Action::None,
            },
            Message::DiscardEdit => match self.ready(ReportKind::Summary) {
                Some(r) if r.edited_md.is_some() => Action::SaveEdit(r.id, None),
                _ => Action::None,
            },
            Message::Copy => match self
                .ready(ReportKind::Summary)
                .and_then(Report::text)
                .map(str::to_owned)
            {
                Some(text) => {
                    self.copied = true;
                    Action::Copy(text)
                }
                None => Action::None,
            },
            Message::CopyHoverEnd => {
                self.copied = false;
                Action::None
            }
            Message::LinkClicked(_) => Action::None,
        }
    }

    /// What sits beside the Work summary heading: the copy icon (with a
    /// tooltip) and, for an edited summary, Discard edit. `None` without a
    /// ready summary.
    pub fn summary_tools(&self) -> Option<Element<'_, Message>> {
        let ready = self.ready(ReportKind::Summary)?;
        ready.text()?;
        let (icon, tip) = if self.copied {
            (theme::Icon::Check, "Copied")
        } else {
            (theme::Icon::Copy, "Copy as Markdown")
        };
        let copy = button(theme::icon(icon).width(16).height(16))
            .padding(theme::ICON_PADDING)
            .style(theme::icon_button)
            .on_press(Message::Copy);
        let copy = mouse_area(tooltip(copy, theme::tip(tip), tooltip::Position::Bottom))
            .on_exit(Message::CopyHoverEnd);
        let mut tools = row![copy].spacing(theme::SPACING / 2.0).align_y(Center);
        if ready.edited_md.is_some() {
            tools = tools.push(
                button(text("Discard edit").size(theme::TEXT_SMALL))
                    .padding([2, 8])
                    .style(theme::text_button)
                    .on_press(Message::DiscardEdit),
            );
        }
        Some(tools.into())
    }

    /// The Work summary's body. Empty when there is no summary to show
    /// (`refresh` leaves `body_src` empty without a summary slot).
    pub fn summary_view(&self) -> Element<'_, Message> {
        if self.body_src.is_empty() {
            return Column::new().into();
        }
        md(&self.body, theme::TEXT_BODY)
    }

    /// The status line for `kind` as an element (with Retry when offered).
    pub fn status_view(&self, kind: ReportKind) -> Option<Element<'_, Message>> {
        let status = self.status(kind)?;
        let style: fn(&Theme) -> text::Style = if status.error {
            theme::danger
        } else {
            theme::muted
        };
        let mut line = row![text(status.text).size(theme::TEXT_SMALL).style(style)]
            .spacing(theme::SPACING / 2.0)
            .align_y(Center);
        if status.retry {
            line = line.push(
                button(text("Retry").size(theme::TEXT_SMALL))
                    .padding([2, 8])
                    .style(theme::text_button)
                    .on_press(Message::Retry(kind)),
            );
        }
        Some(line.into())
    }
}

fn first_line(s: &str) -> &str {
    s.trim().lines().next().unwrap_or("")
}

/// "Mon 14:02".
fn when(report: &Report) -> String {
    report
        .created_at
        .to_zoned_datetime(jiff::tz::TimeZone::system())
        .strftime("%a %H:%M")
        .to_string()
}

/// Renders parsed Markdown with the app's font and accent; links are
/// reported as `LinkClicked` and ignored.
fn md(content: &markdown::Content, size: f32) -> Element<'_, Message> {
    let style = markdown::Style {
        font: theme::FONT,
        inline_code_highlight: markdown::Highlight {
            background: color!(0x78716c, 0.2).into(),
            border: border::rounded(4),
        },
        inline_code_padding: Padding::from([0, 2]),
        inline_code_color: theme::accent_color(),
        inline_code_font: Font::MONOSPACE,
        code_block_font: Font::MONOSPACE,
        link_color: theme::accent_color(),
    };
    // iced's defaults (h1 twice the body) are too loud inside a panel.
    let settings = markdown::Settings {
        h1_size: (size * 1.4).into(),
        h2_size: (size * 1.15).into(),
        h3_size: (size * 1.1).into(),
        h4_size: size.into(),
        code_size: (size * 0.9).into(),
        spacing: (size * 0.75).into(),
        ..markdown::Settings::with_text_size(size, style)
    };
    markdown::view(content.items(), settings).map(Message::LinkClicked)
}

#[cfg(test)]
mod tests {
    use super::*;
    use jiff::Timestamp;
    use jiff::civil::date;

    fn week() -> WeekRef {
        WeekRef::new(date(2026, 11, 16))
    }

    fn report(id: ReportId, kind: ReportKind, text: &str) -> Report {
        Report {
            id,
            kind,
            week_start: week().start,
            status: ReportStatus::Ready,
            digest_json: "{}".into(),
            content_md: Some(text.into()),
            edited_md: None,
            model: Some("test-model".into()),
            endpoint_host: None,
            prompt_version: 4,
            error: None,
            created_at: Timestamp::UNIX_EPOCH,
        }
    }

    fn failed(id: ReportId, kind: ReportKind) -> Report {
        Report {
            status: ReportStatus::Failed,
            content_md: None,
            error: Some("timed out\nmore".into()),
            ..report(id, kind, "")
        }
    }

    fn slot(kind: ReportKind, versions: Vec<Report>) -> ReportSlot {
        ReportSlot {
            kind,
            versions,
            streaming: None,
            blocked: None,
            empty: false,
            stale: false,
        }
    }

    fn data(slots: Vec<ReportSlot>) -> ReportPanelData {
        ReportPanelData {
            week: week(),
            slots,
        }
    }

    #[test]
    fn statuses() {
        let mut p = ReportPanel::new();
        let mut s = slot(ReportKind::Summary, vec![]);
        s.blocked = Some("the API key is locked.".into());
        p.load(data(vec![s.clone()]));
        assert_eq!(
            p.status(ReportKind::Summary).unwrap().text,
            "Can't update: the API key is locked."
        );

        // Blocked but up to date: just when it updated.
        s.versions = vec![report(1, ReportKind::Summary, "x")];
        p.load(data(vec![s.clone()]));
        assert!(
            p.status(ReportKind::Summary)
                .unwrap()
                .text
                .starts_with("Updated")
        );

        s.blocked = None;
        s.streaming = Some(String::new());
        p.load(data(vec![s.clone()]));
        assert_eq!(p.status(ReportKind::Summary).unwrap().text, "Updating…");

        s.streaming = None;
        s.stale = true;
        s.versions.insert(0, failed(2, ReportKind::Summary));
        p.load(data(vec![s.clone()]));
        let st = p.status(ReportKind::Summary).unwrap();
        assert_eq!(st.text, "Couldn't update: timed out");
        assert!(st.error && st.retry);
        // The last good text still shows.
        assert_eq!(p.body_src, "x");
        assert_eq!(
            p.update(Message::Retry(ReportKind::Summary)),
            Action::Generate(ReportKind::Summary, week())
        );

        let mut empty = slot(ReportKind::Summary, vec![]);
        empty.empty = true;
        p.load(data(vec![empty]));
        assert_eq!(
            p.status(ReportKind::Summary).unwrap().text,
            "Nothing done this week yet."
        );
    }

    #[test]
    fn copy_and_discard_edit() {
        let mut p = ReportPanel::new();
        p.load(data(vec![slot(
            ReportKind::Summary,
            vec![report(7, ReportKind::Summary, "hello")],
        )]));
        assert_eq!(p.update(Message::DiscardEdit), Action::None, "not edited");
        assert_eq!(p.update(Message::Copy), Action::Copy("hello".into()));

        let mut edited = report(7, ReportKind::Summary, "hello");
        edited.edited_md = Some("mine".into());
        p.load(data(vec![slot(ReportKind::Summary, vec![edited])]));
        assert_eq!(p.update(Message::Copy), Action::Copy("mine".into()));
        assert!(p.copied);
        assert!(p.summary_tools().is_some());
        p.update(Message::CopyHoverEnd);
        assert!(!p.copied);
        assert_eq!(p.update(Message::DiscardEdit), Action::SaveEdit(7, None));
    }

    #[test]
    fn streaming_text_is_pushed_incrementally() {
        let mut p = ReportPanel::new();
        let streaming = |so_far: &str| {
            let mut s = slot(ReportKind::Summary, vec![]);
            s.streaming = Some(so_far.into());
            data(vec![s])
        };
        p.load(streaming(""));
        let start = p.body_parses;
        p.load(streaming("## High"));
        p.load(streaming("## High"));
        assert_eq!(p.body_parses, start + 1);
        p.load(streaming("## Highlights\n- one"));
        assert_eq!(p.body_parses, start + 2);
        let _ = p.summary_view();
    }

    #[test]
    fn the_previous_summary_stays_while_a_new_one_is_generated() {
        let mut p = ReportPanel::new();
        let mut s = slot(
            ReportKind::Summary,
            vec![report(1, ReportKind::Summary, "## Old summary")],
        );
        s.streaming = Some(String::new());
        p.load(data(vec![s.clone()]));
        assert_eq!(p.body_src, "## Old summary");
        s.streaming = Some("## New".into());
        p.load(data(vec![s]));
        assert_eq!(p.body_src, "## Old summary");
        assert_eq!(p.status(ReportKind::Summary).unwrap().text, "Updating…");
    }

    #[test]
    fn every_state_builds_a_view() {
        let mut p = ReportPanel::new();
        let _ = p.summary_view();
        p.load(data(vec![slot(
            ReportKind::Summary,
            vec![
                failed(1, ReportKind::Summary),
                report(2, ReportKind::Summary, "## Hi"),
            ],
        )]));
        let _ = p.summary_view();
        let _ = p.summary_tools();
        let _ = p.status_view(ReportKind::Summary);
    }
}
